!function(){"use strict";document.getElementById("contact-form").addEventListener("submit",function(e){e.preventDefault();var n=document.getElementById("c-name").value,t=document.getElementById("c-org").value,o=document.getElementById("c-interest").value,i=document.getElementById("c-message").value,c=encodeURIComponent("Silent Visionary Inquiry — "+(o||"General")),m=encodeURIComponent("Name: "+n+"\nOrganization: "+t+"\nInterested in: "+o+"\n\n"+i);window.location.href="mailto:info@silentvisionary.com?subject="+c+"&body="+m})}();